+import type { Measure, TeamMetrics } from "./team-metrics.ts";
+
+const value = (n: number | null) => n === null ? "미확인" : String(n);
+const measured = (m: Measure) => `관측 ${value(m.observed)} / 총량 ${value(m.total)} (${m.coverage})`;
+export function formatTeamMetrics(t: TeamMetrics): string {
+  const q = t.requests;
+  return [
+    "## 팀 측정",
+    `구간: ${t.period.start ?? "시작 미확인"} → ${t.period.end} · ${t.period.unit} · ${t.period.closed ? "닫힘" : "미완료"}`,
+    `요청 ID별: 도달 ${q.reached} (캡틴 답 ${q.captainReply}, 사람 경로 성공 ${q.captainDelivery}) · 실패만 ${q.failedOnly} · 미확인 ${q.unconfirmed} · 옛 식별자 없음 ${q.legacyUnlinkedEvents}`,
+    `수신 의도: 캡틴 ${q.captainIntendedRequests} / 코디네이터 ${q.coordinatorIntendedRequests} · 질문 사건 ${q.captainQuestionEvents}/${q.coordinatorQuestionEvents} · 수신 미상 ${q.recipientUnknownEvents}`,
+    `전달 실패 시도 관측 ${value(q.failedAttemptsObserved)} · 코디네이터 자체 답 관측 ${value(q.coordinatorOwnAnswerObserved)} · 캡틴 개입 총합 미확인(열 중복 가능)`,
+    "| 구분 | 값 |", "|---|---|",
+    ...Object.entries(t.manual).map(([name, m]) => `| 손작업 ${name} | ${measured(m)} |`),
+    ...Object.entries(t.normal).map(([name, m]) => `| 정상 배정·승인 ${name} | ${measured(m)} |`),
+    `| blocking 사건 / 감사 | ${t.quality.blockingLogged} / ${value(t.quality.blockingAudited)} |`,
+    `| 감사 재검토 / 리뷰 실패 사건 / 게이트 실패 | ${value(t.quality.rereviewsAudited)} / ${t.quality.loggedReviewFailures} / ${t.quality.gateFailures} |`,
+    "", "역할별 신고 관측(성적순 아님):",
+    ...t.roles.map((r) => `- ${r.name}: 작업 ms ${value(r.workMs)} · 출력 ${r.outputTokens.map((o) => `${o.tool} ${value(o.output)}`).join(", ") || "미확인"} · ${r.source}`),
+    `cwd 구간 근사(역할 귀속 아님): 작업 ms ${value(t.workerContext.workMs)} · ${t.workerContext.outputs.map((o) => `${o.tool} ${value(o.output)}`).join(", ")}`,
