+export function formatTeamComparison(r: ReturnType<typeof compareTeam>): string {
+  return [`# 팀 비교: ${r.study}`, `판정: ${r.conclusion}`, "| 지표 | 전 | 후 | 증감 | 전 관측 | 후 관측 |", "|---|---|---|---|---|---|", ...r.rows.map((m) => `| ${m.metric} | ${m.before ?? "미확인"} | ${m.after ?? "미확인"} | ${m.delta ?? "미확인"} | ${m.beforeObserved ?? "미확인"} | ${m.afterObserved ?? "미확인"} |`), ...r.reasons.map((s) => `- 이유: ${s}`), ...r.additionalSamplePlan.map((s) => `- 추가 표본 계획: ${s}`), ...r.limits.map((s) => `- 한계: ${s}`)].join("\n\n");
