+  const codes = new Set<string>();
+  for (const r of v.recurringFindings as unknown[]) {
+    fields(r, ["code", "count", "coverage", "refs"]);
+    if (!identifier(r.code) || codes.has(r.code) || !natural(r.count) || r.count < 2 || r.coverage !== "reported" || !proofRefs(dir, r.refs).length) throw new HandoffError("반복 지적은 신고 count≥2와 근거가 필요하다");
